<script setup lang="ts">
import {
  DEFAULT_PASSPHRASE, DEFAULT_RANDOM, MAX_LENGTH, MIN_LENGTH, READABLE_BITS, estimateBits, passphrase, passphraseBits, randomBits, randomPasscode, readablePasscode, strengthOf,
  type PassphraseOptions, type RandomOptions,
} from '@retroboard/application'
import { secureRandomInt } from '~/utils/random'

/**
 * Passcode of a new board (change password-by-default): generated by default, editable, never optional
 * without a warning. Simple mode regenerates a readable code; advanced mode adds a full generator.
 */
const model = defineModel<string>({ required: true })
defineProps<{ advanced: boolean }>()
const { t } = useT()
const { push } = useToasts()
const { $ports } = useNuxtApp()
const shown = ref(true)
const style = ref<'readable' | 'random' | 'passphrase'>('readable')
const random = reactive<RandomOptions>({ ...DEFAULT_RANDOM })
const words = reactive<PassphraseOptions>({ ...DEFAULT_PASSPHRASE })

const bits = computed(() => {
  if (!model.value) return 0
  return estimateBits(model.value)
})
const strength = computed(() => strengthOf(bits.value))

function generate() {
  if (style.value === 'random') model.value = randomPasscode(secureRandomInt, random)
  else if (style.value === 'passphrase') model.value = passphrase(secureRandomInt, words)
  else model.value = readablePasscode(secureRandomInt)
}
const planned = computed(() => style.value === 'random' ? randomBits(random) : style.value === 'passphrase' ? passphraseBits(words) : READABLE_BITS)
async function copy() {
  try { await $ports.clipboard.writeText(model.value); push(t('setup.passcode.copied'), 'ok') } catch { push(t('share.copyFailed'), 'warn') }
}
// A fresh form starts with a readable passcode (the field is empty only when the person clears it on purpose).
onMounted(() => { if (!model.value) generate() })
watch(style, generate)
</script>

<template>
  <section class="pass" data-testid="passcode-block" :aria-label="t('setup.passcode')">
    <label class="lbl" for="setup-passcode">{{ t('setup.passcode') }}</label>
    <div class="row">
      <input
        id="setup-passcode" v-model="model" class="field mono" :type="shown ? 'text' : 'password'" autocomplete="new-password" spellcheck="false" autocapitalize="off"
        :aria-describedby="'pass-hint pass-meter'" data-testid="setup-passcode"
      />
      <button class="mini-btn" type="button" :aria-label="t('setup.passcode.regen')" :title="t('setup.passcode.regen')" data-testid="passcode-regen" @click="generate"><Icon name="lucide:refresh-cw" /></button>
      <button class="mini-btn" type="button" :aria-pressed="shown" :aria-label="shown ? t('setup.passcode.hide') : t('setup.passcode.show')" :title="shown ? t('setup.passcode.hide') : t('setup.passcode.show')" data-testid="passcode-reveal" @click="shown = !shown"><Icon :name="shown ? 'lucide:eye-off' : 'lucide:eye'" /></button>
      <button class="mini-btn" type="button" :disabled="!model" :aria-label="t('setup.passcode.copy')" :title="t('setup.passcode.copy')" data-testid="passcode-copy" @click="copy"><Icon name="lucide:copy" /></button>
    </div>
    <p id="pass-hint" class="muted small">{{ model ? t('setup.passcode.hint') : t('setup.passcode.none') }}</p>
    <p id="pass-meter" class="meter" :data-strength="model ? strength : 'none'" data-testid="passcode-strength">
      <span class="bar" aria-hidden="true"><i :style="{ width: `${Math.min(100, (bits / 100) * 100)}%` }" /></span>
      <span v-if="model">{{ t(`setup.passcode.${strength}`) }} - {{ t('setup.passcode.bits', { n: bits }) }}</span>
      <span v-else>{{ t('setup.passcode.off') }}</span>
    </p>

    <details v-if="advanced" class="gen" data-testid="passcode-generator">
      <summary>{{ t('setup.passcode.generator') }}</summary>
      <div class="pick-seg" role="group" :aria-label="t('setup.passcode.style')">
        <button v-for="s in (['readable', 'random', 'passphrase'] as const)" :key="s" type="button" :class="{ on: style === s }" :aria-pressed="style === s" :data-testid="`passcode-style-${s}`" @click="style = s">{{ t(`setup.passcode.style.${s}`) }}</button>
      </div>
      <div v-if="style === 'random'" class="opts">
        <label class="line">{{ t('setup.passcode.length') }}
          <input v-model.number="random.length" type="range" :min="MIN_LENGTH" :max="MAX_LENGTH" data-testid="passcode-length" @input="generate" />
          <output>{{ random.length }}</output>
        </label>
        <label v-for="k in (['lower', 'upper', 'digits', 'symbols', 'extended'] as const)" :key="k" class="opt">
          <input v-model="random[k]" type="checkbox" :data-testid="`passcode-class-${k}`" @change="generate" /> {{ t(`setup.passcode.class.${k}`) }}
        </label>
        <label class="opt"><input v-model="random.excludeLookalikes" type="checkbox" data-testid="passcode-lookalikes" @change="generate" /> {{ t('setup.passcode.lookalikes') }}</label>
        <label class="opt"><input v-model="random.everyClass" type="checkbox" data-testid="passcode-every" @change="generate" /> {{ t('setup.passcode.every') }}</label>
      </div>
      <div v-else-if="style === 'passphrase'" class="opts">
        <label class="line">{{ t('setup.passcode.words') }}
          <input v-model.number="words.words" type="range" min="3" max="10" data-testid="passcode-words" @input="generate" />
          <output>{{ words.words }}</output>
        </label>
        <label class="line">{{ t('setup.passcode.separator') }}
          <select v-model="words.separator" class="field" data-testid="passcode-separator" @change="generate">
            <option value="-">-</option><option value=".">.</option><option value="_">_</option><option value=" ">{{ t('setup.passcode.space') }}</option>
          </select>
        </label>
        <label class="opt"><input v-model="words.capitalize" type="checkbox" data-testid="passcode-capitalize" @change="generate" /> {{ t('setup.passcode.capitalize') }}</label>
      </div>
      <p class="muted small">{{ t('setup.passcode.planned', { n: planned }) }}</p>
    </details>
  </section>
</template>

<style scoped>
.pass { display: grid; gap: .5rem; }
.row { display: flex; gap: .4rem; align-items: stretch; }
.row .field { flex: 1; min-width: 0; letter-spacing: .04em; }
.small { margin: 0; font-size: var(--fs-sm); }
.meter { margin: 0; display: flex; align-items: center; gap: .6rem; font-size: var(--fs-sm); }
.bar { flex: none; width: 7rem; height: 6px; border-radius: 999px; background: var(--border); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); transition: width .2s; }
.meter[data-strength='weak'] .bar i { background: var(--danger, #c0392b); }
.meter[data-strength='none'] .bar i { width: 0 !important; }
.gen { display: grid; gap: .6rem; padding: .6rem .8rem; border: 1px solid var(--border); border-radius: var(--r-card, 12px); }
.gen summary { cursor: pointer; font-weight: 700; }
.opts { display: grid; gap: .4rem; }
.line { display: flex; align-items: center; gap: .6rem; }
.line input[type='range'] { flex: 1; }
.opt { display: flex; align-items: center; gap: .5rem; cursor: pointer; }
</style>
